def _convert_value(value):
    """Return ``float(value)`` when possible, preserving containers."""
    if isinstance(value, bool):
        return value
    if isinstance(value, tuple):
        return tuple(_convert_value(item) for item in value)
    if isinstance(value, list):
        return [_convert_value(item) for item in value]
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            return value
    if isinstance(value, (int, float)):
        return float(value)
    try:
        return float(value)
    except (TypeError, ValueError):
        return value


def list_to_float(test_list):
    """Write a function to convert all possible convertible elements in the list to float.

    Elements that can be converted to ``float`` (including numeric
    strings and integers, also inside nested tuples/lists) are
    converted; elements that cannot be converted are left unchanged.
    The structure of ``test_list`` is preserved, and its string
    representation is returned, as shown in the issue example:

    >>> list_to_float([("3", "4"), ("1", "26.45"), ("7.32", "8"), ("4", "8")])
    '[(3.0, 4.0), (1.0, 26.45), (7.32, 8.0), (4.0, 8.0)]'
    """
    return str(_convert_value(test_list))
